const D = { density: .55, energy: .6, coupling: .5, speed: 1, scale: 1, hue: 45, x: .5, y: .8, style: 'meadow', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const MAXN = 500;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- rebuild swarm on seed change ----
if (S.seedUsed !== P.seed || !S.fx) {
  S.seedUsed = P.seed;
  S.fx = new Float32Array(MAXN);   // x in 0..1
  S.ay = new Float32Array(MAXN);   // air-normalized y 0..1 (mapped under horizon each frame)
  S.vx = new Float32Array(MAXN);
  S.vy = new Float32Array(MAXN);
  S.ph = new Float32Array(MAXN);   // oscillator phase
  S.fq = new Float32Array(MAXN);   // natural frequency (cycles/sec)
  S.hu = new Float32Array(MAXN);   // per-firefly hue jitter 0..1
  for (let i = 0; i < MAXN; i++) {
    S.fx[i] = fr(i * 4 + 1);
    S.ay[i] = Math.pow(fr(i * 4 + 2), 0.7);            // bias toward lower air (near grass)
    S.vx[i] = (fr(i * 4 + 3) - 0.5) * 0.02;
    S.vy[i] = (fr(i * 4 + 11) - 0.5) * 0.010;
    S.ph[i] = fr(i * 7 + 5);
    S.fq[i] = 0.42 + fr(i * 7 + 6) * 0.34;              // 0.42..0.76 Hz
    S.hu[i] = fr(i * 7 + 9);
  }
  S.coup = P.coupling;
}

// ---- soft glow sprite (size-independent, build once) ----
if (!S.spr) {
  const SZ = 64, sp = createGraphics(SZ, SZ);
  sp.pixelDensity(1); sp.colorMode(HSB, 360, 100, 100, 100); sp.clear(); sp.noStroke();
  for (let r = SZ / 2; r > 0; r -= 1) {
    const t = 1 - r / (SZ / 2);
    sp.fill(0, 0, 100, Math.pow(t, 2.2) * 95);
    sp.circle(SZ / 2, SZ / 2, r * 2);
  }
  S.spr = sp;
}

// ---- background gradient + grass silhouette (cached, size/style/hue/horizon keyed) ----
const hz = Math.max(0.45, Math.min(0.97, P.y));
if (!S.bg || S.bg.width !== width || S.bg.height !== height) { S.bg = createGraphics(width, height); S.bgKey = ''; }
const bgKey = width + 'x' + height + '|' + P.style + '|' + Math.round(P.hue) + '|' + Math.round(hz * 24) + '|' + P.seed;
if (S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const g = S.bg; g.pixelDensity(1); g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  const st = P.style;
  let topC, horC, groundC, glowC, bladeC, hasGrass = true;
  if (st === 'cyan-swarm')      { topC=[206,82,7];  horC=[190,68,17]; groundC=[200,55,6]; glowC=[185,70,20]; bladeC=[195,45,8]; hasGrass=false; }
  else if (st === 'ember')      { topC=[250,42,6];  horC=[22,58,15];  groundC=[16,55,5];  glowC=[28,70,22];  bladeC=[26,45,7]; }
  else if (st === 'spectral')   { topC=[244,60,4];  horC=[262,52,11]; groundC=[250,45,4]; glowC=[280,45,14]; bladeC=[250,35,6]; hasGrass=false; }
  else if (st === 'mono')       { topC=[220,22,7];  horC=[218,14,18]; groundC=[220,12,6]; glowC=[215,10,20]; bladeC=[220,10,8]; }
  else /* meadow */             { topC=[224,74,9];  horC=[208,54,20]; groundC=[150,45,7]; glowC=[46,55,20];  bladeC=[112,52,9]; }
  const hshift = (P.hue - 45);
  const rot = a => [ (a[0] + hshift * 0.15 + 360) % 360, a[1], a[2] ];
  topC = rot(topC); horC = rot(horC); groundC = rot(groundC); glowC = rot(glowC); bladeC = rot(bladeC);
  const hy = hz * height;
  // sky gradient top -> horizon
  for (let y = 0; y < hy; y += 2) {
    const f = y / Math.max(1, hy);
    g.fill(topC[0]+(horC[0]-topC[0])*f, topC[1]+(horC[1]-topC[1])*f, topC[2]+(horC[2]-topC[2])*f);
    g.rect(0, y, width, 2.2);
  }
  // horizon glow band (additive light bleed)
  g.push(); g.blendMode(ADD); g.noStroke();
  for (let k = 0; k < 5; k++) {
    g.fill(glowC[0], glowC[1], glowC[2], 12 - k * 2);
    g.ellipse(width * 0.5, hy, width * (1.1 - k * 0.13), height * (0.28 - k * 0.04));
  }
  g.pop();
  // ground below horizon
  for (let y = hy; y < height; y += 2) {
    const f = (y - hy) / Math.max(1, height - hy);
    g.fill(groundC[0], groundC[1], groundC[2] * (1 - f * 0.55));
    g.rect(0, y, width, 2.2);
  }
  // grass blade silhouette along the horizon
  if (hasGrass) {
    g.noStroke();
    const nb = Math.floor(width / 7);
    for (let b = 0; b < nb; b++) {
      const gx = (b + fr(b * 3 + 40) * 0.9) / nb * width;
      const bh = (0.02 + fr(b * 3 + 41) * 0.07) * height;
      const lean = (fr(b * 3 + 42) - 0.5) * bh * 0.6;
      const w = 1.2 + fr(b * 3 + 43) * 2.2;
      const v = bladeC[2] * (0.6 + fr(b * 3 + 44) * 0.8);
      g.fill(bladeC[0], bladeC[1], v);
      g.beginShape();
      g.vertex(gx - w, hy + 4); g.vertex(gx + w, hy + 4);
      g.vertex(gx + lean, hy - bh);
      g.endShape(CLOSE);
    }
  }
}

// ---- time delta (real-time motion floor from K.t; tolerate resets) ----
if (S.lastT == null || K.t < S.lastT || K.t - S.lastT > 0.5) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (dt <= 0) dt = 1 / Math.max(24, K.fps || 60);
dt = Math.min(dt, 0.08);

// ---- coupling arc: breathe between sync and chaos across the section arc ----
const sec = K.section || 0;
const arc = 0.5 + 0.5 * Math.sin(K.t * 0.045 + sec * 0.9 + (0.5 + K.intensity));
const targetCoup = P.coupling * (0.08 + 0.92 * arc);
S.coup += (targetCoup - (S.coup || 0)) * 0.03;
const eps = S.coup * 0.30 + (A.bass || 0) * 0.05 * P.coupling;

const activeN = Math.max(60, Math.floor(120 + P.density * 380));
const rateMul = 0.4 + P.speed * 0.9;

// ---- advance oscillators + drift, detect fires ----
const fired = S._fired || (S._fired = new Int32Array(MAXN));
let nf = 0;
for (let i = 0; i < activeN; i++) {
  S.ph[i] += dt * S.fq[i] * rateMul * (0.85 + K.intensity * 0.4);
  S.fx[i] += S.vx[i] * dt * rateMul; if (S.fx[i] < 0) S.fx[i] += 1; else if (S.fx[i] > 1) S.fx[i] -= 1;
  S.ay[i] += S.vy[i] * dt * rateMul; if (S.ay[i] < 0) S.ay[i] += 1; else if (S.ay[i] > 1) S.ay[i] -= 1;
  if (S.ph[i] >= 1) { S.ph[i] -= Math.floor(S.ph[i]); fired[nf++] = i; }
}

// ---- Mirollo-Strogatz pulse coupling via a fixed spatial grid ----
if (nf > 0 && eps > 0.001) {
  const GC = 7, R = 0.15, R2 = R * R;
  let head = S._head; if (!head || head.length !== GC * GC) head = S._head = new Int32Array(GC * GC);
  const nxt = S._nxt || (S._nxt = new Int32Array(MAXN));
  head.fill(-1);
  for (let i = 0; i < activeN; i++) {
    let cx = (S.fx[i] * GC) | 0; if (cx < 0) cx = 0; else if (cx >= GC) cx = GC - 1;
    let cy = (S.ay[i] * GC) | 0; if (cy < 0) cy = 0; else if (cy >= GC) cy = GC - 1;
    const ci = cy * GC + cx; nxt[i] = head[ci]; head[ci] = i;
  }
  for (let k = 0; k < nf; k++) {
    const f = fired[k], fx = S.fx[f], fy = S.ay[f];
    let cx = (fx * GC) | 0; if (cx < 0) cx = 0; else if (cx >= GC) cx = GC - 1;
    let cy = (fy * GC) | 0; if (cy < 0) cy = 0; else if (cy >= GC) cy = GC - 1;
    for (let oy = -1; oy <= 1; oy++) {
      const yy = cy + oy; if (yy < 0 || yy >= GC) continue;
      for (let ox = -1; ox <= 1; ox++) {
        const xx = cx + ox; if (xx < 0 || xx >= GC) continue;
        let j = head[yy * GC + xx];
        while (j !== -1) {
          if (j !== f) {
            let dx = S.fx[j] - fx; if (dx > 0.5) dx -= 1; else if (dx < -0.5) dx += 1;
            const dy = S.ay[j] - fy, d2 = dx * dx + dy * dy;
            if (d2 < R2) {
              S.ph[j] += eps * (1 - d2 / R2);
              if (S.ph[j] >= 1) S.ph[j] = 0.985;   // cap: fire next frame, no same-frame avalanche
            }
          }
          j = nxt[j];
        }
      }
    }
  }
}

// ---- render ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.bg, 0, 0);
pop();

const aMul = P.alpha / 100;
const rms = A.rms || 0, bass = A.bass || 0, treb = A.treble || 0;
const baseR = u * 0.011 * P.scale;
const bloom = u * 0.055 * P.energy * P.scale;
const st = P.style;
push();
blendMode(ADD);
imageMode(CENTER);
noStroke();
for (let i = 0; i < activeN; i++) {
  let bright = Math.pow(S.ph[i], 5);
  bright = bright * (0.9 + rms * 0.6) + 0.03;         // faint charge glow + audio lift
  if (bright > 1.2) bright = 1.2;
  const x = S.fx[i] * width;
  const y = (0.03 + S.ay[i] * (hz - 0.05)) * height;
  let hh, ss;
  if (st === 'cyan-swarm')    { hh = 176 + S.hu[i] * 26; ss = 78; }
  else if (st === 'ember')    { hh = 8 + S.hu[i] * 30;   ss = 96; }
  else if (st === 'spectral') { hh = (S.fx[i] * 250 + S.ay[i] * 90 + K.t * 6) % 360; ss = 88; }
  else if (st === 'mono')     { hh = 210; ss = 6 + bright * 10; }
  else                        { hh = 44 + S.hu[i] * 66; ss = 82; }  // meadow amber->green
  hh = (hh + (P.hue - 45) + 360) % 360;
  const sz = (baseR + bright * bloom * (1 + bass * 0.8)) * 2.1;
  const al = (20 + bright * 66) * aMul;
  tint(hh, ss, 100, al > 96 ? 96 : al);
  image(S.spr, x, y, sz, sz);
}
blendMode(BLEND);
imageMode(CORNER);
pop();
